-- Phase 3 / Checkpoint B: additive project structure administration.
alter table public.admin_audit_logs drop constraint if exists admin_audit_logs_resource_type_check;
alter table public.admin_audit_logs
  add column project_id uuid references public.projects(id),
  add constraint admin_audit_logs_resource_type_check check(resource_type in ('organization','membership','invitation','project','building','floor','unit_type','unit'));
create index admin_audit_logs_project_created_idx on public.admin_audit_logs(project_id,created_at desc,id);

alter table public.projects drop constraint if exists projects_status_check;
alter table public.projects drop constraint if exists projects_check;
alter table public.projects
  add column country text not null default 'BR', add column state text, add column city text,
  add column address text, add column currency text not null default 'BRL',
  add column estimated_delivery_date date,
  add column public_inventory_enabled boolean not null default false,
  add column visual_experience_enabled boolean not null default false,
  add column version bigint not null default 1 check(version>0),
  add column created_by uuid references auth.users(id), add column updated_by uuid references auth.users(id),
  add constraint projects_status_check check(status in ('draft','ready','published','archived')),
  add constraint projects_country_check check(country ~ '^[A-Z]{2}$'),
  add constraint projects_currency_check check(currency ~ '^[A-Z]{3}$'),
  add constraint projects_coordinates_check check((latitude is null or latitude between -90 and 90) and (longitude is null or longitude between -180 and 180));
update public.projects set public_inventory_enabled=true,visual_experience_enabled=true where slug='escobar-residences' and status='published';
alter table public.projects add constraint projects_slug_global_key unique(slug);
update public.projects set public_inventory_enabled=true,visual_experience_enabled=true where id='00000000-0000-4000-8000-000000000002' and organization_id='00000000-0000-4000-8000-000000000001';
create function private.preserve_escobar_capabilities() returns trigger language plpgsql set search_path='' as $$begin if new.id='00000000-0000-4000-8000-000000000002' and new.organization_id='00000000-0000-4000-8000-000000000001' and new.status='published' then new.public_inventory_enabled=true;new.visual_experience_enabled=true;end if;return new;end$$;
create trigger projects_preserve_escobar_capabilities before insert on public.projects for each row execute function private.preserve_escobar_capabilities();

alter table public.buildings
  add column display_order integer not null default 0, add column active boolean not null default true,
  add column version bigint not null default 1 check(version>0),
  add column created_by uuid references auth.users(id), add column updated_by uuid references auth.users(id);
update public.buildings set default_camera_config=jsonb_build_object('mode','existing_viewer_defaults','validated',true)
where id='00000000-0000-4000-8000-000000000003' and project_id='00000000-0000-4000-8000-000000000002' and default_camera_config='{}'::jsonb;
create function private.preserve_escobar_camera() returns trigger language plpgsql set search_path='' as $$begin if new.id='00000000-0000-4000-8000-000000000003' and new.project_id='00000000-0000-4000-8000-000000000002' and new.default_camera_config='{}'::jsonb then new.default_camera_config=jsonb_build_object('mode','existing_viewer_defaults','validated',true);end if;return new;end$$;
create trigger buildings_preserve_escobar_camera before insert on public.buildings for each row execute function private.preserve_escobar_camera();
alter table public.floors drop constraint if exists floors_number_check;
alter table public.floors
  add column code text, add column display_order integer not null default 0,
  add column height_meters numeric check(height_meters is null or height_meters>0),
  add column active boolean not null default true, add column version bigint not null default 1 check(version>0),
  add column created_by uuid references auth.users(id), add column updated_by uuid references auth.users(id),
  add column updated_at timestamptz not null default now();
update public.floors set code=number::text,display_order=number where code is null;
create function private.default_floor_code() returns trigger language plpgsql set search_path='' as $$begin new.code=coalesce(nullif(btrim(new.code),''),new.number::text);if new.display_order=0 then new.display_order=new.number;end if;return new;end$$;
create trigger floors_default_code before insert on public.floors for each row execute function private.default_floor_code();
alter table public.floors alter column code set not null;
alter table public.floors add constraint floors_code_check check(btrim(code)<>''),add constraint floors_building_code_key unique(building_id,code);
create trigger floors_updated_at before update on public.floors for each row execute function public.set_updated_at();

alter table public.unit_types
  add column code text, add column description text,
  add column bathrooms integer check(bathrooms is null or bathrooms>=0),
  add column parking_spaces integer check(parking_spaces is null or parking_spaces>=0),
  add column active boolean not null default true, add column version bigint not null default 1 check(version>0),
  add column created_by uuid references auth.users(id), add column updated_by uuid references auth.users(id),
  add constraint unit_types_area_order_check check(total_area_m2 is null or total_area_m2>=private_area_m2);
update public.unit_types set code=lower(regexp_replace(name,'[^A-Za-z0-9]+','-','g')) where code is null;
create function private.default_unit_type_code() returns trigger language plpgsql set search_path='' as $$begin new.code=coalesce(nullif(btrim(new.code),''),lower(trim(both '-' from regexp_replace(new.name,'[^A-Za-z0-9]+','-','g'))));return new;end$$;
create trigger unit_types_default_code before insert on public.unit_types for each row execute function private.default_unit_type_code();
alter table public.unit_types alter column code set not null;
alter table public.unit_types add constraint unit_types_code_check check(btrim(code)<>''),add constraint unit_types_project_code_key unique(project_id,code);

alter table public.units
  add column external_reference text, add column currency text not null default 'BRL',
  add constraint units_project_code_key unique(project_id,code),
  add constraint units_currency_check check(currency ~ '^[A-Z]{3}$');

create index projects_admin_idx on public.projects(organization_id,status,name,id);
create index buildings_admin_idx on public.buildings(project_id,active,display_order,code,id);
create index floors_admin_idx on public.floors(building_id,active,display_order,code,id);
create index unit_types_admin_idx on public.unit_types(project_id,active,code,id);

create function private.can_manage_project(p_organization_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select private.is_platform_admin() or exists(select 1 from public.organization_members m join public.organizations o on o.id=m.organization_id where m.organization_id=p_organization_id and m.user_id=auth.uid() and m.role='organization_admin' and m.active and m.removed_at is null and o.status='active')
$$;
create function private.require_project_manager(p_organization_id uuid) returns void language plpgsql security definer set search_path='' as $$begin perform private.require_active_user();if not private.can_manage_project(p_organization_id) then perform private.raise_admin_error('not_found');end if;end$$;
create function private.audit_structure(p_org uuid,p_project uuid,p_type text,p_id uuid,p_action text,p_old jsonb,p_new jsonb,p_reason text default null) returns void language sql security definer set search_path='' as $$
 insert into public.admin_audit_logs(organization_id,project_id,resource_type,resource_id,action,old_values,new_values,reason,performed_by) values(p_org,p_project,p_type,p_id,p_action,coalesce(p_old,'{}'),coalesce(p_new,'{}'),p_reason,auth.uid())
$$;

create function public.admin_list_projects(p_organization_id uuid,p_page integer default 1,p_page_size integer default 25,p_search text default null,p_status text default null)
returns table(id uuid,organization_id uuid,name text,slug text,description text,status text,country text,state text,city text,address text,latitude numeric,longitude numeric,timezone text,currency text,estimated_delivery_date date,north_offset_degrees numeric,public_inventory_enabled boolean,visual_experience_enabled boolean,version bigint,building_count bigint,floor_count bigint,unit_type_count bigint,unit_count bigint,total_count bigint)
language plpgsql stable security definer set search_path='' as $$begin perform private.require_active_user();if p_page<1 or p_page_size not between 1 and 100 then perform private.raise_admin_error('invalid_input');end if;if not private.has_organization_access(p_organization_id) then perform private.raise_admin_error('not_found');end if;return query select p.id,p.organization_id,p.name,p.slug,p.description,p.status,p.country,p.state,p.city,p.address,p.latitude,p.longitude,p.timezone,p.currency,p.estimated_delivery_date,p.north_offset_degrees,p.public_inventory_enabled,p.visual_experience_enabled,p.version,(select count(*) from public.buildings b where b.project_id=p.id),(select count(*) from public.floors f join public.buildings b on b.id=f.building_id where b.project_id=p.id),(select count(*) from public.unit_types t where t.project_id=p.id),(select count(*) from public.units u where u.project_id=p.id),count(*) over() from public.projects p where p.organization_id=p_organization_id and (p_status is null or p.status=p_status) and (p_search is null or p.name ilike '%'||btrim(p_search)||'%' or p.slug ilike '%'||btrim(p_search)||'%') order by p.name,p.id offset (p_page-1)*p_page_size limit p_page_size;end$$;

create function public.admin_create_project(p_organization_id uuid,p_name text,p_slug text,p_description text,p_country text,p_state text,p_city text,p_address text,p_latitude numeric,p_longitude numeric,p_timezone text,p_currency text,p_estimated_delivery_date date,p_north_offset_degrees numeric)
returns public.projects language plpgsql security definer set search_path='' as $$declare v public.projects;begin perform private.require_project_manager(p_organization_id);if btrim(coalesce(p_name,''))='' or private.normalize_slug(p_slug)='' then perform private.raise_admin_error('invalid_input');end if;insert into public.projects(id,organization_id,name,slug,description,status,country,state,city,address,latitude,longitude,timezone,currency,estimated_delivery_date,north_offset_degrees,public_inventory_enabled,visual_experience_enabled,created_by,updated_by) values(gen_random_uuid(),p_organization_id,btrim(p_name),private.normalize_slug(p_slug),nullif(btrim(p_description),''),'draft',upper(p_country),nullif(btrim(p_state),''),nullif(btrim(p_city),''),nullif(btrim(p_address),''),p_latitude,p_longitude,p_timezone,upper(p_currency),p_estimated_delivery_date,p_north_offset_degrees,false,false,auth.uid(),auth.uid()) returning * into v;perform private.audit_structure(v.organization_id,v.id,'project',v.id,'project.created',null,to_jsonb(v)-array['theme_config','default_unit_code']);return v;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

create function public.admin_update_project(p_id uuid,p_expected_version bigint,p_name text,p_slug text,p_description text,p_country text,p_state text,p_city text,p_address text,p_latitude numeric,p_longitude numeric,p_timezone text,p_currency text,p_estimated_delivery_date date,p_north_offset_degrees numeric)
returns public.projects language plpgsql security definer set search_path='' as $$declare o public.projects;n public.projects;begin select * into o from public.projects where id=p_id for update;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(o.organization_id);if o.status='archived' then perform private.raise_admin_error('invalid_transition');end if;if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;update public.projects set name=btrim(p_name),slug=private.normalize_slug(p_slug),description=nullif(btrim(p_description),''),country=upper(p_country),state=nullif(btrim(p_state),''),city=nullif(btrim(p_city),''),address=nullif(btrim(p_address),''),latitude=p_latitude,longitude=p_longitude,timezone=p_timezone,currency=upper(p_currency),estimated_delivery_date=p_estimated_delivery_date,north_offset_degrees=p_north_offset_degrees,updated_by=auth.uid(),version=version+1 where id=p_id returning * into n;perform private.audit_structure(n.organization_id,n.id,'project',n.id,'project.updated',to_jsonb(o)-array['theme_config','default_unit_code'],to_jsonb(n)-array['theme_config','default_unit_code']);return n;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

create function public.admin_validate_project_readiness(p_project_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$declare p public.projects;b int;f int;t int;u int;errors jsonb='[]';warnings jsonb='[]';begin select * into p from public.projects where id=p_project_id;if not found or not private.has_organization_access(p.organization_id) then perform private.raise_admin_error('not_found');end if;select count(*) into b from public.buildings where project_id=p.id and active;select count(*) into f from public.floors x join public.buildings y on y.id=x.building_id where y.project_id=p.id and x.active and y.active;select count(*) into t from public.unit_types where project_id=p.id and active;select count(*) into u from public.units where project_id=p.id;if b=0 then errors=errors||'"missing_building"';end if;if f=0 then errors=errors||'"missing_floor"';end if;if t=0 then errors=errors||'"missing_unit_type"';end if;if u=0 then errors=errors||'"missing_unit"';end if;if p.visual_experience_enabled and not exists(select 1 from public.buildings where project_id=p.id and btrim(model_path)<>'') then errors=errors||'"missing_visual_configuration"';end if;if not p.public_inventory_enabled then warnings=warnings||'"public_inventory_disabled"';end if;return jsonb_build_object('ready',jsonb_array_length(errors)=0,'errors',errors,'warnings',warnings,'buildings',b,'floors',f,'unitTypes',t,'units',u,'invalidReferences',0,'duplicateCodes',0,'missingValues',jsonb_array_length(errors));end$$;

create function public.admin_change_project_status(p_id uuid,p_expected_version bigint,p_new_status text,p_reason text,p_confirm boolean default false)
returns public.projects language plpgsql security definer set search_path='' as $$declare o public.projects;n public.projects;org_status text;checkup jsonb;begin select * into o from public.projects where id=p_id for update;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(o.organization_id);if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if btrim(coalesce(p_reason,''))='' then perform private.raise_admin_error('invalid_input');end if;select status into org_status from public.organizations where id=o.organization_id;if p_new_status='ready' and o.status='draft' then checkup=public.admin_validate_project_readiness(o.id);if not (checkup->>'ready')::boolean then perform private.raise_admin_error('project_not_ready');end if;elsif p_new_status='published' and o.status='ready' then if org_status<>'active' then perform private.raise_admin_error('forbidden');end if;elsif p_new_status='ready' and o.status='published' then if not p_confirm then perform private.raise_admin_error('invalid_input');end if;elsif p_new_status='archived' and o.status in ('draft','ready','published') then if not p_confirm then perform private.raise_admin_error('invalid_input');end if;else perform private.raise_admin_error('invalid_transition');end if;update public.projects set status=p_new_status,published_at=case when p_new_status='published' then now() else published_at end,public_inventory_enabled=case when p_new_status='published' then public_inventory_enabled else false end,visual_experience_enabled=case when p_new_status='published' then visual_experience_enabled else false end,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(n.organization_id,n.id,'project',n.id,case when p_new_status='archived' then 'project.archived' else 'project.status_changed' end,jsonb_build_object('status',o.status),jsonb_build_object('status',n.status),btrim(p_reason));return n;end$$;

create function public.admin_set_project_capabilities(p_id uuid,p_expected_version bigint,p_public_inventory_enabled boolean,p_visual_experience_enabled boolean)
returns public.projects language plpgsql security definer set search_path='' as $$declare o public.projects;n public.projects;begin select * into o from public.projects where id=p_id for update;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(o.organization_id);if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if o.status not in ('ready','published') or (p_visual_experience_enabled and not exists(select 1 from public.buildings where project_id=o.id and btrim(model_path)<>'')) then perform private.raise_admin_error('invalid_input');end if;update public.projects set public_inventory_enabled=p_public_inventory_enabled,visual_experience_enabled=p_visual_experience_enabled,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(n.organization_id,n.id,'project',n.id,'project.capabilities_updated',jsonb_build_object('public_inventory_enabled',o.public_inventory_enabled,'visual_experience_enabled',o.visual_experience_enabled),jsonb_build_object('public_inventory_enabled',n.public_inventory_enabled,'visual_experience_enabled',n.visual_experience_enabled));return n;end$$;

-- A placeholder created by the generic building form is never valid 3D configuration.
create or replace function public.admin_set_project_capabilities(p_id uuid,p_expected_version bigint,p_public_inventory_enabled boolean,p_visual_experience_enabled boolean)
returns public.projects language plpgsql security definer set search_path='' as $$
declare o public.projects;n public.projects;
begin
  select * into o from public.projects where id=p_id for update;
  if not found then perform private.raise_admin_error('not_found');end if;
  perform private.require_project_manager(o.organization_id);
  if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;
  if o.status not in ('ready','published') or (p_visual_experience_enabled and not exists(
    select 1 from public.buildings where project_id=o.id and active and btrim(model_path)<>'' and model_path<>'__not_configured__'
  )) then perform private.raise_admin_error('invalid_input');end if;
  update public.projects set public_inventory_enabled=p_public_inventory_enabled,visual_experience_enabled=p_visual_experience_enabled,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;
  perform private.audit_structure(n.organization_id,n.id,'project',n.id,'project.capabilities_updated',jsonb_build_object('public_inventory_enabled',o.public_inventory_enabled,'visual_experience_enabled',o.visual_experience_enabled),jsonb_build_object('public_inventory_enabled',n.public_inventory_enabled,'visual_experience_enabled',n.visual_experience_enabled));
  return n;
end$$;

create function private.project_visual_validation(p_project_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare p public.projects;org_status text;errors jsonb='[]';begin select * into p from public.projects where id=p_project_id;if not found then return jsonb_build_object('valid',false,'errors',jsonb_build_array('not_found'));end if;select status into org_status from public.organizations where id=p.organization_id;if org_status<>'active' then errors=errors||'"organization_inactive"';end if;if p.status not in ('ready','published') then errors=errors||'"project_status_incompatible"';end if;if not exists(select 1 from public.buildings b where b.project_id=p.id and b.active) then errors=errors||'"missing_active_building"';end if;if exists(select 1 from public.buildings b where b.project_id=p.id and b.active and (btrim(b.model_path)='' or b.model_path='__not_configured__')) then errors=errors||'"missing_building_model"';end if;if exists(select 1 from public.buildings b where b.project_id=p.id and b.active and (b.default_camera_config='{}'::jsonb or not coalesce((b.default_camera_config->>'validated')::boolean,false))) then errors=errors||'"invalid_camera_configuration"';end if;if exists(select 1 from public.units u join public.buildings b on b.id=u.building_id where u.project_id=p.id and u.published and b.active and btrim(u.model_object_id)='') then errors=errors||'"missing_unit_proxy"';end if;if exists(select 1 from public.units u where u.project_id=p.id and u.published group by u.building_id,u.model_object_id having count(*)>1) then errors=errors||'"duplicate_unit_proxy"';end if;return jsonb_build_object('valid',jsonb_array_length(errors)=0,'errors',errors);end$$;
create function public.admin_validate_project_visual(p_project_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare org uuid;begin select p.organization_id into org from public.projects p where p.id=p_project_id;if not found or not private.has_organization_access(org) then perform private.raise_admin_error('not_found');end if;return private.project_visual_validation(p_project_id);end$$;

create or replace function public.admin_validate_project_readiness(p_project_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare p public.projects;org_status text;b int;f int;t int;u int;invalid_count int;errors jsonb='[]';warnings jsonb='[]';begin select * into p from public.projects where id=p_project_id;if not found or not private.has_organization_access(p.organization_id) then perform private.raise_admin_error('not_found');end if;select status into org_status from public.organizations where id=p.organization_id;select count(*) into b from public.buildings where project_id=p.id and active;select count(*) into f from public.floors x join public.buildings y on y.id=x.building_id where y.project_id=p.id and x.active and y.active;select count(*) into t from public.unit_types where project_id=p.id and active;select count(*) into u from public.units where project_id=p.id;select count(*) into invalid_count from public.units x left join public.buildings b1 on b1.id=x.building_id and b1.project_id=x.project_id left join public.floors f1 on f1.id=x.floor_id and f1.building_id=x.building_id left join public.unit_types t1 on t1.id=x.unit_type_id and t1.project_id=x.project_id where x.project_id=p.id and (b1.id is null or f1.id is null or t1.id is null or not b1.active or not f1.active or not t1.active);if org_status<>'active' then errors=errors||'"organization_inactive"';end if;if btrim(p.name)='' or p.slug='' or p.country!~'^[A-Z]{2}$' or p.currency!~'^[A-Z]{3}$' or btrim(p.timezone)='' then errors=errors||'"missing_project_fields"';end if;if b=0 then errors=errors||'"missing_building"';end if;if f=0 then errors=errors||'"missing_floor"';end if;if t=0 then errors=errors||'"missing_unit_type"';end if;if u=0 then errors=errors||'"missing_unit"';end if;if invalid_count>0 then errors=errors||'"inactive_or_invalid_structure"';end if;if exists(select 1 from public.unit_types x where x.project_id=p.id and x.active and (x.private_area_m2<=0 or (x.total_area_m2 is not null and x.total_area_m2<x.private_area_m2) or x.bedrooms<0 or x.suites<0 or x.bathrooms is null or x.bathrooms<1)) then errors=errors||'"missing_residential_attributes"';end if;if not p.public_inventory_enabled then warnings=warnings||'"public_inventory_disabled"';end if;return jsonb_build_object('ready',jsonb_array_length(errors)=0,'errors',errors,'warnings',warnings,'buildings',b,'floors',f,'unitTypes',t,'units',u,'invalidReferences',invalid_count,'duplicateCodes',0,'missingValues',jsonb_array_length(errors));end$$;

create or replace function public.admin_set_project_capabilities(p_id uuid,p_expected_version bigint,p_public_inventory_enabled boolean,p_visual_experience_enabled boolean) returns public.projects language plpgsql security definer set search_path='' as $$declare o public.projects;n public.projects;org_status text;visual jsonb;begin select * into o from public.projects where id=p_id for update;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(o.organization_id);if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;select status into org_status from public.organizations where id=o.organization_id;if o.status<>'published' and p_public_inventory_enabled then perform private.raise_admin_error('invalid_transition');end if;if org_status<>'active' and (p_public_inventory_enabled or p_visual_experience_enabled) then perform private.raise_admin_error('forbidden');end if;if p_visual_experience_enabled then visual=private.project_visual_validation(o.id);if not (visual->>'valid')::boolean then perform private.raise_admin_error('project_not_ready');end if;end if;update public.projects set public_inventory_enabled=p_public_inventory_enabled,visual_experience_enabled=p_visual_experience_enabled,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(n.organization_id,n.id,'project',n.id,'project.capabilities_updated',jsonb_build_object('public_inventory_enabled',o.public_inventory_enabled,'visual_experience_enabled',o.visual_experience_enabled),jsonb_build_object('public_inventory_enabled',n.public_inventory_enabled,'visual_experience_enabled',n.visual_experience_enabled));return n;end$$;

-- Generic list RPCs expose explicit structural columns and stable ordering.
create function public.admin_list_buildings(p_project_id uuid) returns table(id uuid,project_id uuid,code text,name text,display_order integer,active boolean,version bigint,floor_count bigint,unit_count bigint,model_path text)
language plpgsql stable security definer set search_path='' as $$declare org uuid;begin select p.organization_id into org from public.projects p where p.id=p_project_id;if not found or not private.has_organization_access(org) then perform private.raise_admin_error('not_found');end if;return query select b.id,b.project_id,b.code,b.name,b.display_order,b.active,b.version,(select count(*) from public.floors f where f.building_id=b.id),(select count(*) from public.units u where u.building_id=b.id),b.model_path from public.buildings b where b.project_id=p_project_id order by b.display_order,b.code,b.id;end$$;
create function public.admin_list_floors(p_building_id uuid) returns table(id uuid,building_id uuid,code text,label text,floor_number integer,display_order integer,height_meters numeric,active boolean,version bigint,unit_count bigint,model_object_id text)
language plpgsql stable security definer set search_path='' as $$declare org uuid;begin select p.organization_id into org from public.buildings b join public.projects p on p.id=b.project_id where b.id=p_building_id;if not found or not private.has_organization_access(org) then perform private.raise_admin_error('not_found');end if;return query select f.id,f.building_id,f.code,f.label,f.number,f.display_order,f.height_meters,f.active,f.version,(select count(*) from public.units u where u.floor_id=f.id),f.model_object_id from public.floors f where f.building_id=p_building_id order by f.display_order,f.number,f.code,f.id;end$$;
create function public.admin_list_unit_types(p_project_id uuid) returns table(id uuid,project_id uuid,code text,name text,description text,private_area numeric,total_area numeric,bedrooms integer,suites integer,bathrooms integer,parking_spaces integer,active boolean,version bigint,unit_count bigint,interior_project_id text,floor_plan_path text)
language plpgsql stable security definer set search_path='' as $$declare org uuid;begin select p.organization_id into org from public.projects p where p.id=p_project_id;if not found or not private.has_organization_access(org) then perform private.raise_admin_error('not_found');end if;return query select t.id,t.project_id,t.code,t.name,t.description,t.private_area_m2,t.total_area_m2,t.bedrooms,t.suites,t.bathrooms,t.parking_spaces,t.active,t.version,(select count(*) from public.units u where u.unit_type_id=t.id),t.interior_project_id,t.floor_plan_path from public.unit_types t where t.project_id=p_project_id order by t.code,t.id;end$$;

-- One mutation per structural aggregate; visual fields are never accepted.
create function public.admin_save_building(p_id uuid,p_project_id uuid,p_expected_version bigint,p_code text,p_name text,p_display_order integer,p_active boolean)
returns public.buildings language plpgsql security definer set search_path='' as $$declare p public.projects;o public.buildings;n public.buildings;begin select * into p from public.projects where id=p_project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;if btrim(coalesce(p_code,''))='' or btrim(coalesce(p_name,''))='' then perform private.raise_admin_error('invalid_input');end if;if p_id is null then insert into public.buildings(id,project_id,code,name,model_path,floor_count,display_order,active,created_by,updated_by) values(gen_random_uuid(),p.id,btrim(p_code),btrim(p_name),'__not_configured__',1,p_display_order,p_active,auth.uid(),auth.uid()) returning * into n;perform private.audit_structure(p.organization_id,p.id,'building',n.id,'building.created',null,to_jsonb(n)-array['model_path','default_camera_config']);else select * into o from public.buildings where id=p_id and project_id=p.id for update;if not found then perform private.raise_admin_error('not_found');end if;if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if not p_active and exists(select 1 from public.units where building_id=o.id) then perform private.raise_admin_error('dependency_conflict');end if;update public.buildings set code=btrim(p_code),name=btrim(p_name),display_order=p_display_order,active=p_active,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(p.organization_id,p.id,'building',n.id,'building.updated',to_jsonb(o)-array['model_path','default_camera_config'],to_jsonb(n)-array['model_path','default_camera_config']);end if;return n;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;end$$;

create function public.admin_save_floor(p_id uuid,p_building_id uuid,p_expected_version bigint,p_code text,p_label text,p_floor_number integer,p_display_order integer,p_height_meters numeric,p_active boolean)
returns public.floors language plpgsql security definer set search_path='' as $$declare b public.buildings;p public.projects;o public.floors;n public.floors;begin select * into b from public.buildings where id=p_building_id;select * into p from public.projects where id=b.project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;if btrim(coalesce(p_code,''))='' or btrim(coalesce(p_label,''))='' then perform private.raise_admin_error('invalid_input');end if;if p_id is null then insert into public.floors(id,building_id,code,label,number,display_order,height_meters,active,created_by,updated_by) values(gen_random_uuid(),b.id,btrim(p_code),btrim(p_label),p_floor_number,p_display_order,p_height_meters,p_active,auth.uid(),auth.uid()) returning * into n;perform private.audit_structure(p.organization_id,p.id,'floor',n.id,'floor.created',null,to_jsonb(n)-'model_object_id');else select * into o from public.floors where id=p_id and building_id=b.id for update;if not found then perform private.raise_admin_error('not_found');end if;if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if not p_active and exists(select 1 from public.units where floor_id=o.id) then perform private.raise_admin_error('dependency_conflict');end if;update public.floors set code=btrim(p_code),label=btrim(p_label),number=p_floor_number,display_order=p_display_order,height_meters=p_height_meters,active=p_active,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(p.organization_id,p.id,'floor',n.id,'floor.updated',to_jsonb(o)-'model_object_id',to_jsonb(n)-'model_object_id');end if;return n;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

create function public.admin_preview_floor_generation(p_building_id uuid,p_start integer,p_end integer,p_code_pattern text default '{n}',p_label_pattern text default 'Pavimento {n}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare org uuid;items jsonb;conflicts jsonb;begin select p.organization_id into org from public.buildings b join public.projects p on p.id=b.project_id where b.id=p_building_id;if not found or not private.has_organization_access(org) then perform private.raise_admin_error('not_found');end if;if p_end<p_start or p_end-p_start+1>100 or position('{n}' in p_code_pattern)=0 then perform private.raise_admin_error('invalid_input');end if;select coalesce(jsonb_agg(jsonb_build_object('floorNumber',n,'code',replace(p_code_pattern,'{n}',n::text),'label',replace(p_label_pattern,'{n}',n::text),'displayOrder',n) order by n),'[]') into items from generate_series(p_start,p_end)n;select coalesce(jsonb_agg(code),'[]') into conflicts from jsonb_to_recordset(items) x("floorNumber" integer,code text,label text,"displayOrder" integer) where exists(select 1 from public.floors f where f.building_id=p_building_id and (f.code=x.code or f.number=x."floorNumber"));return jsonb_build_object('items',items,'conflicts',conflicts,'canConfirm',jsonb_array_length(conflicts)=0);end$$;
create function public.admin_confirm_floor_generation(p_building_id uuid,p_start integer,p_end integer,p_code_pattern text,p_label_pattern text,p_operation_id uuid) returns integer language plpgsql security definer set search_path='' as $$declare b public.buildings;p public.projects;preview jsonb;n integer;fid uuid;begin select * into b from public.buildings where id=p_building_id;select * into p from public.projects where id=b.project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);preview=public.admin_preview_floor_generation(b.id,p_start,p_end,p_code_pattern,p_label_pattern);if not (preview->>'canConfirm')::boolean then perform private.raise_admin_error('duplicate_code');end if;for n in p_start..p_end loop fid=gen_random_uuid();insert into public.floors(id,building_id,code,label,number,display_order,active,created_by,updated_by) values(fid,b.id,replace(p_code_pattern,'{n}',n::text),replace(p_label_pattern,'{n}',n::text),n,n,true,auth.uid(),auth.uid());end loop;perform private.audit_structure(p.organization_id,p.id,'building',b.id,'floor.batch_created',null,jsonb_build_object('start',p_start,'end',p_end,'count',p_end-p_start+1,'operation_id',p_operation_id));return p_end-p_start+1;end$$;

create function public.admin_save_unit_type(p_id uuid,p_project_id uuid,p_expected_version bigint,p_code text,p_name text,p_description text,p_private_area numeric,p_total_area numeric,p_bedrooms integer,p_suites integer,p_bathrooms integer,p_parking_spaces integer,p_active boolean)
returns public.unit_types language plpgsql security definer set search_path='' as $$declare p public.projects;o public.unit_types;n public.unit_types;begin select * into p from public.projects where id=p_project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;if p_id is null then insert into public.unit_types(id,project_id,code,name,description,private_area_m2,total_area_m2,bedrooms,suites,bathrooms,parking_spaces,active,created_by,updated_by) values(gen_random_uuid(),p.id,btrim(p_code),btrim(p_name),nullif(btrim(p_description),''),p_private_area,p_total_area,p_bedrooms,p_suites,p_bathrooms,p_parking_spaces,p_active,auth.uid(),auth.uid()) returning * into n;perform private.audit_structure(p.organization_id,p.id,'unit_type',n.id,'unit_type.created',null,to_jsonb(n)-array['interior_project_id','floor_plan_path']);else select * into o from public.unit_types where id=p_id and project_id=p.id for update;if not found then perform private.raise_admin_error('not_found');end if;if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if not p_active and exists(select 1 from public.units where unit_type_id=o.id) then perform private.raise_admin_error('dependency_conflict');end if;update public.unit_types set code=btrim(p_code),name=btrim(p_name),description=nullif(btrim(p_description),''),private_area_m2=p_private_area,total_area_m2=p_total_area,bedrooms=p_bedrooms,suites=p_suites,bathrooms=p_bathrooms,parking_spaces=p_parking_spaces,active=p_active,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(p.organization_id,p.id,'unit_type',n.id,'unit_type.updated',to_jsonb(o)-array['interior_project_id','floor_plan_path'],to_jsonb(n)-array['interior_project_id','floor_plan_path']);end if;return n;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

create function public.admin_create_structural_unit(p_project_id uuid,p_building_id uuid,p_floor_id uuid,p_unit_type_id uuid,p_unit_code text,p_external_reference text,p_orientation text,p_view_type text,p_sun_exposure text,p_currency text,p_parking_spaces integer,p_initial_price numeric default null,p_initial_status text default 'available',p_initial_published boolean default false)
returns public.units language plpgsql security definer set search_path='' as $$declare p public.projects;u public.units;begin select * into p from public.projects where id=p_project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);if p.status='archived' or p_initial_status<>'available' or p_initial_published then perform private.raise_admin_error('invalid_input');end if;if not exists(select 1 from public.buildings where id=p_building_id and project_id=p.id and active) or not exists(select 1 from public.floors where id=p_floor_id and building_id=p_building_id and active) or not exists(select 1 from public.unit_types where id=p_unit_type_id and project_id=p.id and active) then perform private.raise_admin_error('invalid_input');end if;insert into public.units(id,project_id,building_id,floor_id,unit_type_id,code,external_reference,status,price_brl,parking_spaces,orientation,view_type,sun_exposure,model_object_id,published,currency) values(gen_random_uuid(),p.id,p_building_id,p_floor_id,p_unit_type_id,btrim(p_unit_code),nullif(btrim(p_external_reference),''),'available',p_initial_price,p_parking_spaces,p_orientation,p_view_type,p_sun_exposure,'UNMAPPED_'||gen_random_uuid(),false,upper(p_currency)) returning * into u;perform private.audit_structure(p.organization_id,p.id,'unit',u.id,'unit.created',null,to_jsonb(u)-array['reserved_by','reserved_at','reserved_until','model_object_id']);return u;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

create function public.admin_update_structural_unit(p_id uuid,p_expected_version bigint,p_building_id uuid,p_floor_id uuid,p_unit_type_id uuid,p_external_reference text,p_orientation text,p_view_type text,p_sun_exposure text,p_currency text,p_parking_spaces integer)
returns public.units language plpgsql security definer set search_path='' as $$declare o public.units;n public.units;p public.projects;begin select * into o from public.units where id=p_id for update;if not found then perform private.raise_admin_error('not_found');end if;select * into p from public.projects where id=o.project_id;perform private.require_project_manager(p.organization_id);if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;if not exists(select 1 from public.buildings where id=p_building_id and project_id=p.id and active) or not exists(select 1 from public.floors where id=p_floor_id and building_id=p_building_id and active) or not exists(select 1 from public.unit_types where id=p_unit_type_id and project_id=p.id and active) then perform private.raise_admin_error('invalid_input');end if;update public.units set building_id=p_building_id,floor_id=p_floor_id,unit_type_id=p_unit_type_id,external_reference=nullif(btrim(p_external_reference),''),orientation=p_orientation,view_type=p_view_type,sun_exposure=p_sun_exposure,currency=upper(p_currency),parking_spaces=p_parking_spaces,version=version+1 where id=o.id returning * into n;perform private.audit_structure(p.organization_id,p.id,'unit',n.id,'unit.structure_updated',to_jsonb(o)-array['price_brl','status','published','reserved_by','reserved_at','reserved_until','model_object_id'],to_jsonb(n)-array['price_brl','status','published','reserved_by','reserved_at','reserved_until','model_object_id']);return n;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

create function public.admin_save_unit_type_confirmed(p_id uuid,p_project_id uuid,p_expected_version bigint,p_code text,p_name text,p_description text,p_private_area numeric,p_total_area numeric,p_bedrooms integer,p_suites integer,p_bathrooms integer,p_parking_spaces integer,p_active boolean,p_confirm_impact boolean default false)
returns public.unit_types language plpgsql security definer set search_path='' as $$declare p public.projects;o public.unit_types;n public.unit_types;affected integer=0;material boolean=false;begin select * into p from public.projects where id=p_project_id;if not found then perform private.raise_admin_error('not_found');end if;perform private.require_project_manager(p.organization_id);if p.status='archived' then perform private.raise_admin_error('invalid_transition');end if;if p_id is null then if p_bathrooms is null or p_bathrooms<1 then perform private.raise_admin_error('invalid_input');end if;insert into public.unit_types(id,project_id,code,name,description,private_area_m2,total_area_m2,bedrooms,suites,bathrooms,parking_spaces,active,created_by,updated_by) values(gen_random_uuid(),p.id,btrim(p_code),btrim(p_name),nullif(btrim(p_description),''),p_private_area,p_total_area,p_bedrooms,p_suites,p_bathrooms,p_parking_spaces,p_active,auth.uid(),auth.uid()) returning * into n;perform private.audit_structure(p.organization_id,p.id,'unit_type',n.id,'unit_type.created',null,(to_jsonb(n)-array['interior_project_id','floor_plan_path'])||jsonb_build_object('affected_units',0));else select * into o from public.unit_types where id=p_id and project_id=p.id for update;if not found then perform private.raise_admin_error('not_found');end if;if o.version<>p_expected_version then perform private.raise_admin_error('version_conflict');end if;perform 1 from public.units where unit_type_id=o.id for update;select count(*) into affected from public.units where unit_type_id=o.id;material=(o.private_area_m2 is distinct from p_private_area or o.total_area_m2 is distinct from p_total_area or o.bedrooms is distinct from p_bedrooms or o.suites is distinct from p_suites or o.bathrooms is distinct from p_bathrooms);if affected>0 and material and not p_confirm_impact then perform private.raise_admin_error('dependency_conflict');end if;if not p_active and affected>0 then perform private.raise_admin_error('dependency_conflict');end if;update public.unit_types set code=btrim(p_code),name=btrim(p_name),description=nullif(btrim(p_description),''),private_area_m2=p_private_area,total_area_m2=p_total_area,bedrooms=p_bedrooms,suites=p_suites,bathrooms=p_bathrooms,parking_spaces=p_parking_spaces,active=p_active,updated_by=auth.uid(),version=version+1 where id=o.id returning * into n;perform private.audit_structure(p.organization_id,p.id,'unit_type',n.id,'unit_type.updated',to_jsonb(o)-array['interior_project_id','floor_plan_path'],(to_jsonb(n)-array['interior_project_id','floor_plan_path'])||jsonb_build_object('affected_units',affected));end if;return n;exception when unique_violation then perform private.raise_admin_error('duplicate_code');return null;when check_violation then perform private.raise_admin_error('invalid_input');return null;end$$;

revoke all on function public.admin_save_unit_type(uuid,uuid,bigint,text,text,text,numeric,numeric,integer,integer,integer,integer,boolean) from authenticated;

-- Public inventory requires the explicit capability without changing its shape.
create or replace function public.get_public_inventory(p_organization_slug text,p_project_slug text,p_unit_code text default null)
returns table(organization_slug text,project_slug text,project_name text,project_id uuid,building_id uuid,building_code text,building_name text,building_model_path text,unit_id uuid,unit_code text,floor_id uuid,floor_number integer,unit_type_id uuid,unit_type_name text,status text,price_brl numeric,parking_spaces integer,bedrooms integer,suites integer,private_area_m2 numeric,total_area_m2 numeric,orientation text,view_type text,sun_exposure text,model_object_id text,interior_project_id text,updated_at timestamptz)
language sql stable security definer set search_path='' as $$select o.slug,p.slug,p.name,p.id,b.id,b.code,b.name,b.model_path,u.id,u.code,f.id,f.number,t.id,t.name,u.status,u.price_brl,u.parking_spaces,t.bedrooms,t.suites,t.private_area_m2,t.total_area_m2,u.orientation,u.view_type,u.sun_exposure,u.model_object_id,t.interior_project_id,u.updated_at from public.organizations o join public.projects p on p.organization_id=o.id join public.buildings b on b.project_id=p.id join public.units u on u.project_id=p.id and u.building_id=b.id join public.floors f on f.id=u.floor_id and f.building_id=b.id join public.unit_types t on t.id=u.unit_type_id and t.project_id=p.id where o.slug=p_organization_slug and o.status='active' and p.slug=p_project_slug and p.status='published' and p.public_inventory_enabled and p.published_at is not null and b.active and f.active and t.active and u.published and u.status in ('available','reserved','sold') and (p_unit_code is null or u.code=p_unit_code) order by f.display_order,f.number,u.code$$;

